#VRML V2.0 utf8

PROTO Stairway [
  field SFInt32 steps   10      # Number of steps
  field SFVec3f size    1 .2 .5 # Size of each step
  field SFFloat overlap .5      # Amount of overlap of each step
                                # 0 - no overlap
                                # 1 - full overlap
]
{
  DEF transform1 Transform {}
  DEF script1 Script {
    eventOut MFNode  output
    field    SFInt32 steps   IS steps
    field    SFVec3f size    IS size
    field    SFFloat overlap IS overlap
    url "javascript:
      function initialize() {
        var Texto='';
        for (i=0; i<steps; i++) {
          Texto += 'Transform {';
          Texto += ' translation 0 '+(i*size.y)+' -'+(i*size.z*(1-overlap));
          Texto += '   children [';
          Texto += '        Shape {';
          Texto += '             appearance Appearance {';
          Texto += '                material Material {';
          Texto += '                }';
          Texto += '             }';
          Texto += '             geometry Box {';
          Texto += '                size ' + size;
          Texto += '             }';
          Texto += '        }';
          Texto += '   ]';
          Texto += '}';
        }
        output = Browser.createVrmlFromString(Texto);
      }
    "
  }
  ROUTE script1.output TO transform1.addChildren
}
